          desc: R`ملف الـ bat (أو [[.cmd]]، نفس الحكاية) ملف نصي فيه أوامر CMD ورا بعض، بيتشغّل كلها بدبل كليك أو باسمه. اعمله: [[notepad hello.bat]] من CMD (هيسألك تعمل ملف جديد، Yes)، أو من VS Code. اكتب المثال واحفظ. لو بتحفظ من Notepad بـ Save As، اختار «All Files» عشان ميتحفظش [[hello.bat.txt]]، وشغّل إظهار الامتدادات في Explorer (تاب «الملفات وامتداداتها»).

جوه الملف: [[@echo off]] أول سطر في كل bat تقريبًا، من غيره CMD بيطبع كل أمر قبل ما ينفّذه، و [[@]] بتخفي السطر ده نفسه. [[REM]] أو [[::]] تعليق. [[title]] بيغيّر عنوان النافذة. [[echo]] بيطبع، و [[echo.]] بنقطة لازقة بيطبع سطر فاضي. و [[%USERNAME%]] و [[%date%]] و [[%time%]] متغيرات جاهزة (درس رموز CMD). و [[pause]] بيطبع «Press any key to continue» ويستنى.

التشغيل بطريقتين، والفرق مهم: من CMD مفتوح اكتب [[hello.bat]] أو [[hello]] (CMD بيشغّل من الفولدر الحالي من غير [[.\]] عكس PowerShell)، والنافذة بتفضل بعد ما يخلص فتقرا الناتج. أو بدبل كليك من Explorer: ويندوز بيفتح نافذة جديدة تشغّل الملف وتقفل أول ما يخلص، عشان كده [[pause]] في الآخر بيسيبها مفتوحة لحد ما تدوس زرار. ولو الدبل كليك فتح نافذة واتقفلت قبل ما تقرا حاجة، شغّله من CMD تشوف الـ error.`,
          example: R`@echo off
REM hello.bat: my first batch file
title My first script
echo Hello, %USERNAME%!
echo Today is %date% and the time is %time%
echo.
echo Files here:
dir /b
pause`,
          try: R`احفظه hello.bat وشغّله بدبل كليك. وبعدين امسح سطر [[@echo off]] وشغّله تاني. وبعدين امسح [[pause]] وشغّله بدبل كليك.`,
