            how: R`[[.bat]] و [[.cmd]] الاتنين بيتشغّلوا بـ cmd.exe. الفرق الوحيد تقريبًا في تفاصيل errorlevel مع أوامر قليلة، فاستخدم .bat عادي.

الترميز: احفظ الملف ANSI أو UTF-8 من غير BOM. لو فيه عربي، شوف درس [[chcp 65001]]، و «UTF-8 with BOM» بيبوّظ أول سطر.

[[@echo off]]: [[echo off]] بيقفل طباعة الأوامر من السطر اللي بعده، و [[@]] قبلها بتخفي السطر ده نفسه. ولو عايز تشوف كل أمر وهو بيتنفذ وانت بتدوّر على غلطة، اكتب [[echo on]] أو امسح السطر مؤقتًا، ده المقابل لـ [[bash -x]].

[[REM]] أمر بيتنفذ ومش بيعمل حاجة. [[::]] شكلها تعليق بس هي label مبيتنداش، شغالة في أي مكان بره الأقواس، وجوه بلوك [[( )]] ممكن تعمل مشاكل، فاستخدم REM هناك.

التشغيل:
من CMD: [[hello.bat]] أو [[hello]] أو بالمسار الكامل. CMD بيدوّر في الفولدر الحالي الأول وبعدين الـ PATH.
دبل كليك: ويندوز بيشغّل [[cmd /c hello.bat]]، والـ [[/c]] معناها «نفّذ واقفل». والفولدر الحالي ساعتها هو فولدر الملف، بس من اختصار أو Task Scheduler ممكن يبقى حاجة تانية، والحل [[cd /d "%~dp0"]] (درس %~dp0).
من PowerShell: [[.\hello.bat]]، و PowerShell بيشغّله بـ cmd.
وعشان النافذة تفضل مفتوحة من غير pause: [[cmd /k hello.bat]].

[[pause]] لو عايز رسالة بتاعتك: [[echo Done. Press any key... & pause >nul]].`,
            when: "أوامر قليلة بتكررها، أو زرار لحد مش بيستخدم الترمنال، أو launcher لسكربت PowerShell (درس batch ولا PowerShell؟).",
            mistakes: R`الملف يتحفظ [[hello.bat.txt]] فيتفتح في Notepad بدل ما يشتغل. أو تسمّي الملف باسم أمر موجود زي [[ping.bat]] أو [[git.bat]] في نفس الفولدر، فلما السكربت يكتب [[ping]] يشغّل نفسه بدل الأمر الحقيقي ويلف للأبد. أو تنسى [[pause]] فالدبل كليك يقفل قبل ما تقرا. أو تحط pause في سكربت هيتشغّل من Task Scheduler فيفضل مستني للأبد.`
