            "ادخل فولدر السكربت نفسه، حتى لو على درايف تاني.",
            "اسحب اللي اترفع من أجهزة تانية الأول ([[--autostash]] يشيل تعديلاتك على جنب ويرجّعها)، ولو فشل روح لـ :fail.",
            "ضيف كل التغييرات.",
